contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will call Put to deposit some ether from this test contract into c for msg.sender == address(this).
    // Then attempt a Collect and assert that if Collect does not revert and the recorded balance decreased,
    // then address(this).balance increased by exactly that decrease and c's recorded balance equals previous - amount.

    function run(uint putLock, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);
        // Ensure MinSum is something (contract may be uninitialized); we cannot call internal vars.
        // First, deposit putAmount into c using Put.
        // Note: call must be top-level statement.
        c.Put{value: putAmount}(putLock); if (__ESBMC_reverted()) return;

        // Read holder balance before Collect via public getter Acc(address)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        // attempt Collect; it may revert; capture that
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint balThis = address(this).balance;
        uint balC = address(c).balance;

        // Assert general invariant:
        // If call did not revert and afterBalance < beforeBalance, then the decrease equals collectAmount and this contract's balance increased by that same amount.
        // Also require that afterBalance == beforeBalance if transfer didn't happen.
        assert(
            reverted || (
                // either collect did not revert and transfer happened exactly
                (beforeBalance >= collectAmount && afterBalance + collectAmount == beforeBalance && balThis >= collectAmount && balC + collectAmount <= beforeBalance + balC) 
                ||
                // or collect did not revert but balance unchanged (Collect chose not to execute because preconditions like unlock/minsum failed)
                (afterBalance == beforeBalance)
            )
        );
    }

    receive() external payable {}
}

