// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 putLock, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.Put{value: putAmount}(putLock) {} catch { return; }
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint balThis = address(this).balance;
        uint balC = address(c).balance;
        assertTrue(reverted || (
                // either collect did not revert and transfer happened exactly
                (beforeBalance >= collectAmount && afterBalance + collectAmount == beforeBalance && balThis >= collectAmount && balC + collectAmount <= beforeBalance + balC) 
                ||
                // or collect did not revert but balance unchanged (Collect chose not to execute because preconditions like unlock/minsum failed)
                (afterBalance == beforeBalance)
            ));
    }

    function testFuzz_run(uint256 putLock, uint256 putAmount, uint256 collectAmount) public {
        _run(putLock, putAmount, collectAmount);
    }

    receive() external payable {}
}
